tree=('x1',10,[3,5,7],('x2',5,[10,14,18],[30,40]))
def visit(node,features,trace):
 if isinstance(node,list):return sum(node)/len(node),trace
 key,cut,left,right=node;return visit(left if features[key]<=cut else right,features,trace+[key])
